const $=id=>document.getElementById(id), colors=['#b8f343','#bf82f7','#ffad58','#68dacc','#ff7da3','#77a8ff'];
let rows=BASE.rows.map(r=>({...r})),demo=true,current=null,scaling=null,scores=[],dirty=false;
const fmt=v=>v===null||!Number.isFinite(v)?'No aplica':Number(v).toLocaleString('es-PE',{maximumFractionDigits:3});
function color(g){return g<0?'#7a8177':colors[g%colors.length];}
function el(tag,attrs={},txt){const e=document.createElementNS('http://www.w3.org/2000/svg',tag);Object.entries(attrs).forEach(([k,v])=>e.setAttribute(k,v));if(txt!==undefined)e.textContent=txt;return e;}
function textNode(tag,txt,cls){const e=document.createElement(tag);e.textContent=txt;if(cls)e.className=cls;return e;}
function download(name,text,type){const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([text],{type}));a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);}
function csvField(v){const raw=String(v);const s=/^[=+@\t\r]/.test(raw)?"'"+raw:raw;return '"'+s.replaceAll('"','""')+'"';}
function axisOptions(){for(const id of ['xaxis','yaxis']){$(id).replaceChildren();if(demo){$(''+id).add(new Option('PCA · componente 1','pc0'));$(id).add(new Option('PCA · componente 2','pc1'));}BASE.features.forEach((f,j)=>$(id).add(new Option(BASE.names[j],f)));} $('xaxis').value=demo?'pc0':'pH';$('yaxis').value=demo?'pc1':'Organic_Matter_pct';}
function compute(){const z=Engine.standardize(rows.map(r=>BASE.features.map(f=>r[f])));scaling=z;if(new Set(z.z.map(r=>r.join('|'))).size<Number($('k').value)&&$('algorithm').value==='kmeans')throw Error('Se necesitan más muestras diferentes para ese K.');scores=[];for(let k=2;k<=6;k++){const m=demo?BASE.models[k]:Engine.kmeans(z.z,k);scores.push({k,silhouette:demo?m.silhouette:Engine.silhouette(z.z,m.labels),inertia:m.inertia,model:m});}if($('algorithm').value==='kmeans'){const k=Number($('k').value),s=scores.find(s=>s.k===k);current={...s.model,silhouette:s.silhouette,algorithm:'K-Means',params:'K='+k};}else{const eps=Number($('eps').value),min=Number($('minpts').value);if(!Number.isInteger(min)||min<2||min>20)throw Error('El mínimo de vecinos debe ser un entero de 2 a 20.');current={...Engine.dbscan(z.z,eps,min),algorithm:'DBSCAN',params:'ε='+eps+' / mínimo='+min};current.silhouette=Engine.silhouette(z.z,current.labels);}dirty=false;render();}
function render(){const groups=[...new Set(current.labels.filter(g=>g>=0))].sort((a,b)=>a-b),noise=current.labels.filter(g=>g<0).length;$('datasetBadge').textContent=(demo?'TERRAGEM':'CSV propio')+' / '+rows.length+' muestras';$('nMetric').textContent=rows.length;$('gMetric').textContent=groups.length;$('gCaption').textContent=noise?noise+' muestras de ruido':'grupos encontrados';$('sMetric').textContent=current.silhouette===null?'—':fmt(current.silhouette);$('iMetric').textContent=current.algorithm==='K-Means'?fmt(current.inertia):noise;$('fourthLabel').textContent=current.algorithm==='K-Means'?'INERCIA':'RUIDO';$('fourthCaption').textContent=current.algorithm==='K-Means'?'suma de distancias²':'muestras sin grupo';$('legend').replaceChildren();[...groups,...(noise?[-1]:[])].forEach(g=>{const e=textNode('span',g<0?'Ruido':'Grupo '+(g+1));e.style.setProperty('--c',color(g));$('legend').append(e);});$('profiles').replaceChildren();for(const g of groups){let subset=rows.filter((_,i)=>current.labels[i]===g),avg=BASE.features.map(f=>subset.reduce((s,r)=>s+r[f],0)/subset.length);const block=document.createElement('div');block.className='profile';const title=document.createElement('div');title.append(textNode('b','Grupo '+(g+1)),textNode('p',subset.length+' muestras'));const bar=document.createElement('div');bar.className='bar';bar.style.setProperty('--c',color(g));bar.style.width=Math.max(10,subset.length/rows.length*100)+'%';title.append(bar);block.append(title,textNode('p',BASE.names.map((name,j)=>name+': '+fmt(avg[j])).join(' · ')));$('profiles').append(block);}if(noise)$('profiles').append(textNode('p',noise+' muestras se identificaron como ruido: revisar individualmente.','hint'));drawScatter();drawScores();table();$('status').textContent=current.algorithm+' · '+current.params+' · análisis actualizado.';$('error').textContent='';$('selected').textContent='Toca un punto para conocer su muestra.';}
function drawScatter(){const svg=$('scatter');svg.replaceChildren();const xf=$('xaxis').value,yf=$('yaxis').value,get=(r,i,f)=>f.startsWith('pc')?BASE.pca[i][Number(f.slice(2))]:r[f],xs=rows.map((r,i)=>get(r,i,xf)),ys=rows.map((r,i)=>get(r,i,yf));const minx=Math.min(...xs),maxx=Math.max(...xs),miny=Math.min(...ys),maxy=Math.max(...ys),rx=maxx-minx||1,ry=maxy-miny||1,px=v=>65+(v-minx)/rx*655,py=v=>310-(v-miny)/ry*265;for(let t=0;t<=4;t++){let xx=65+t/4*655,yy=310-t/4*265;svg.append(el('line',{x1:65,x2:720,y1:yy,y2:yy,stroke:'#e3e8dc','stroke-dasharray':'3 5'}),el('text',{x:xx,y:330,'text-anchor':'middle',fill:'#849078','font-size':10},fmt(minx+rx*t/4)),el('text',{x:55,y:yy+3,'text-anchor':'end',fill:'#849078','font-size':10},fmt(miny+ry*t/4)));}rows.forEach((r,i)=>{const c=el('circle',{cx:px(xs[i]),cy:py(ys[i]),r:6.5,fill:color(current.labels[i]),'fill-opacity':.8,stroke:'#fafbf6','stroke-width':2,tabindex:0,role:'button','aria-label':r.Sample_ID+', '+(current.labels[i]<0?'Ruido':'Grupo '+(current.labels[i]+1))});c.append(el('title',{},r.Sample_ID+' · '+BASE.names.map((n,j)=>n+': '+r[BASE.features[j]]).join(' / ')));const select=()=>{$('selected').textContent=r.Sample_ID+' — '+(current.labels[i]<0?'Ruido':'Grupo '+(current.labels[i]+1))+' | '+BASE.names.map((n,j)=>n+': '+fmt(r[BASE.features[j]])).join(' · ');};c.addEventListener('click',select);c.addEventListener('keydown',e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();select();}});svg.append(c);});svg.append(el('text',{x:390,y:362,'text-anchor':'middle',fill:'#64785d','font-size':11},$('xaxis').selectedOptions[0].textContent),el('text',{x:14,y:176,transform:'rotate(-90 14 176)','text-anchor':'middle',fill:'#64785d','font-size':11},$('yaxis').selectedOptions[0].textContent));$('plotnote').textContent=demo&&(xf.startsWith('pc')||yf.startsWith('pc'))?'PCA 1 + 2 explica '+fmt(BASE.variance.reduce((a,b)=>a+b,0)*100)+'% de la variación. El agrupamiento utiliza las 7 variables, no solo estos ejes.':'Los ejes muestran valores originales. El agrupamiento utiliza las 7 variables estandarizadas.';}
function drawScores(){const svg=$('scores');svg.replaceChildren();const valid=scores.filter(s=>s.silhouette!==null);const best=valid.reduce((a,b)=>b.silhouette>a.silhouette?b:a,valid[0]);for(let j=0;j<=4;j++){let y=175-j*36;svg.append(el('line',{x1:38,x2:455,y1:y,y2:y,stroke:'#e2e7d8'}),el('text',{x:29,y:y+3,'text-anchor':'end','font-size':10,fill:'#849078'},(j/4).toFixed(2)));}scores.forEach((s,i)=>{const x=65+i*80,v=s.silhouette??0;svg.append(el('rect',{x,y:175-Math.max(0,v)*144,width:40,height:Math.max(1,v*144),rx:4,fill:s.k===best?.k?'#3f775b':'#c6d2ba'}),el('text',{x:x+20,y:195,'text-anchor':'middle','font-size':11,fill:'#63765c'},'K='+s.k),el('text',{x:x+20,y:164-Math.max(0,v)*144,'text-anchor':'middle','font-size':10,fill:'#63765c'},fmt(s.silhouette)));});$('recommendation').textContent=best?'Mayor silueta explorada: K='+best.k+' ('+fmt(best.silhouette)+'). Revisa grupos unitarios y casos extremos. No equivale a precisión ni demuestra una clasificación agronómica.':'No hay una silueta válida para esta configuración.';}
function table(){const q=$('search').value.trim().toLowerCase();$('thead').replaceChildren();const tr=document.createElement('tr');['Muestra',...BASE.names,'Grupo'].forEach(v=>tr.append(textNode('th',v)));$('thead').append(tr);$('tbody').replaceChildren();let n=0;rows.forEach((r,i)=>{const g=current.labels[i],name=g<0?'Ruido':'Grupo '+(g+1);if(![r.Sample_ID,name].join(' ').toLowerCase().includes(q))return;n++;const tr=document.createElement('tr');tr.append(textNode('td',r.Sample_ID));BASE.features.forEach(f=>tr.append(textNode('td',fmt(r[f]))));const td=document.createElement('td'),badge=textNode('span',name,'grouplabel');badge.style.setProperty('--c',color(g));td.append(badge);tr.append(td);$('tbody').append(tr);});$('rowCount').textContent=n+' de '+rows.length+' muestras · '+current.algorithm+' / '+current.params;}
function markDirty(){$('status').textContent='Parámetros modificados. Pulsa Analizar suelos para aplicarlos.';dirty=true;}
$('k').value=BASE.bestK;$('kValue').value=BASE.bestK;
$('k').oninput=()=>{$('kValue').value=$('k').value;markDirty();};$('eps').oninput=()=>{$('epsValue').value=$('eps').value;markDirty();};$('minpts').oninput=markDirty;
$('algorithm').onchange=()=>{$('kmControls').hidden=$('algorithm').value!=='kmeans';$('dbControls').hidden=$('algorithm').value!=='dbscan';markDirty();};
$('run').onclick=()=>{try{compute();}catch(e){$('error').textContent=e.message;}};
$('upload').onchange=async e=>{const file=e.target.files[0];if(!file)return;try{if(file.size>2e6)throw Error('El archivo supera 2 MB.');const parsed=Engine.parseCSV(await file.text(),BASE.features);if(new Set(parsed.map(r=>BASE.features.map(f=>r[f]).join('|'))).size<6)throw Error('El archivo necesita al menos 6 muestras con propiedades diferentes.');rows=parsed;demo=false;axisOptions();compute();}catch(err){$('error').textContent=err.message;}e.target.value='';};
$('reset').onclick=()=>{rows=BASE.rows.map(r=>({...r}));demo=true;$('search').value='';axisOptions();compute();};$('xaxis').onchange=drawScatter;$('yaxis').onchange=drawScatter;$('search').oninput=table;
$('export').onclick=()=>{const head=['Sample_ID',...BASE.features,'Grupo','Algoritmo','Parametros'];const csv=[head,...rows.map((r,i)=>[r.Sample_ID,...BASE.features.map(f=>r[f]),current.labels[i]<0?'Ruido':current.labels[i]+1,current.algorithm,current.params])].map(r=>r.map(csvField).join(',')).join('\r\n');download('AgroGrupos_resultados.csv','\uFEFF'+csv,'text/csv;charset=utf-8');};
function reportText(){const sizes={};current.labels.forEach(g=>{const name=g<0?'Ruido':'Grupo '+(g+1);sizes[name]=(sizes[name]||0)+1;});return ['AGROGRUPOS · REPORTE DEL ANÁLISIS','Lorena Abigail Coca Ccorpa · Tarea 6 · PIAD-427 / HT-02','Origen: '+(demo?'TERRAGEM, 29 casos funcionales publicados':'CSV propio del usuario'),'Método: '+current.algorithm+' · '+current.params,'Variables: '+BASE.names.join(', '),'Transformación: media cero y desviación poblacional uno.','Muestras: '+rows.length,'Silueta: '+fmt(current.silhouette),'Tamaños: '+JSON.stringify(sizes),'','PERFILES PROMEDIO',...Array.from($('profiles').children).map(e=>e.textContent),'','LÍMITES','La silueta no es precisión. Los grupos no definen fertilidad ni dosis de insumos. Casos extremos y muestra pequeña condicionan la interpretación.','Datos base: Delgado Santiago, C. E. (2026). TERRAGEM. Zenodo. https://doi.org/10.5281/zenodo.19103772. CC BY 4.0.','Web: https://agrogrupos.onrender.com/'].join('\n');}
$('report').onclick=()=>download('AgroGrupos_reporte.txt',reportText(),'text/plain;charset=utf-8');$('print').onclick=()=>window.print();axisOptions();compute();
